SET LOCAL lock_timeout = '5s';

ALTER TABLE whatsapp_lines ADD COLUMN IF NOT EXISTS respect_daily_recommendation boolean NOT NULL DEFAULT false;
ALTER TABLE campaigns ADD COLUMN IF NOT EXISTS budget_resume_at timestamptz;
ALTER TABLE campaigns DROP CONSTRAINT IF EXISTS campaigns_pause_reason_check;
ALTER TABLE campaigns ADD CONSTRAINT campaigns_pause_reason_check CHECK (pause_reason IN (
 'manual','no_eligible_lines','all_lines_outside_schedule','systemic_error','config_missing',
 'frequency_exhausted','unknown','assigned_line_unavailable','risk_detected','line_budget'
));
CREATE INDEX IF NOT EXISTS campaigns_budget_resume_due ON campaigns(budget_resume_at,id)
 WHERE status='paused' AND pause_reason='line_budget';

-- Shared across concurrent campaigns; local dates are America/Argentina/Buenos_Aires.
CREATE TABLE IF NOT EXISTS line_campaign_daily_budgets (
 line_id uuid NOT NULL REFERENCES whatsapp_lines(id) ON DELETE CASCADE,
 budget_date date NOT NULL,
 consumed integer NOT NULL DEFAULT 0 CHECK(consumed>=0),
 updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(line_id,budget_date)
);
CREATE TABLE IF NOT EXISTS line_send_budget_reservations (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 line_id uuid NOT NULL REFERENCES whatsapp_lines(id) ON DELETE CASCADE,
 send_key text NOT NULL UNIQUE,
 purpose text NOT NULL CHECK(purpose IN ('campaign','automation','service')),
 budget_date date NOT NULL,
 status text NOT NULL DEFAULT 'reserved' CHECK(status IN ('reserved','consumed','released')),
 day_reset_at timestamptz NOT NULL,
 hour_reset_at timestamptz NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS line_send_budget_line_date ON line_send_budget_reservations(line_id,budget_date);

-- The same business's advisors and automations share one durable conversation guard.
CREATE TABLE IF NOT EXISTS automation_conversation_safety (
 phone text NOT NULL,
 scope_key text NOT NULL,
 last_human_at timestamptz,
 last_automation_at timestamptz,
 handoff_event_key text,
 updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(phone,scope_key)
);
ALTER TABLE automation_message_jobs ADD COLUMN IF NOT EXISTS dispatch_authorized_at timestamptz;
ALTER TABLE automation_message_jobs ADD COLUMN IF NOT EXISTS body_fingerprint text;
ALTER TABLE automation_message_jobs ADD COLUMN IF NOT EXISTS link_fingerprints text[] NOT NULL DEFAULT '{}';
CREATE INDEX IF NOT EXISTS automation_jobs_contact_recent ON automation_message_jobs(phone,agent_code,created_at DESC);
CREATE INDEX IF NOT EXISTS automation_jobs_source_status ON automation_message_jobs(phone,provider,source_id,status);

ALTER TABLE line_campaign_daily_budgets ENABLE ROW LEVEL SECURITY;
ALTER TABLE line_send_budget_reservations ENABLE ROW LEVEL SECURITY;
